#include "intelligence_runtime.h"
#include "autosave_gate.h"
#include <iostream>
#include <fstream>
#include <filesystem>
#include <functional>
#include <thread>
using namespace npcai;
namespace fs=std::filesystem;
#define CHECK(x) do{if(!(x))throw std::runtime_error(std::string(__FILE__)+":"+std::to_string(__LINE__)+" " #x);}while(0)
static void Until(std::function<bool()> test){auto end=RealMilliseconds()+6000;while(!test()){if(RealMilliseconds()>end)throw std::runtime_error("test deadline");std::this_thread::sleep_for(std::chrono::milliseconds(10));}}
static std::string Dir(){auto p=fs::temp_directory_path()/("npcai-test-"+SessionId());fs::create_directories(p);return p.string();}
static WorldFrame Frame(uint64_t at=1000,int hour=14){WorldFrame f;f.at=at;f.minuteOfDay=hour*60;f.weatherAvailable=true;f.vehiclesAvailable=true;WorldObserverSample o;o.id="NPC-A";o.forward={0,1,0};o.losAvailable=true;o.playerVisible=true;f.observers.push_back(o);return f;}
static PerceivedEvent Event(std::string id,WorldKind kind=WorldKind::TimeJump){PerceivedEvent p;p.event.id=id;p.event.kind=kind;p.event.at=2000;p.event.intensity=.9f;p.event.confidence=.95f;p.confidence=.8f;p.channel="ambient_inference_no_direct_visual_claim";return p;}
static Request R(){Request r;r.npcId="NPC-A";r.conversationId="c1";r.message="Oi, parceiro";r.requestId="NPC-A.c1.r1";return r;}
static void TimeChanges(){WorldEventDetector d;auto f=Frame();CHECK(d.Update(f).empty());auto out=d.Update(Frame(1500,23));CHECK(std::any_of(out.begin(),out.end(),[](const auto&e){return e.kind==WorldKind::TimeJump;}));CHECK(std::any_of(out.begin(),out.end(),[](const auto&e){return e.kind==WorldKind::Night;}));for(const auto&e:out)CHECK(!e.causeConfirmed);d.Reset();f=Frame(1,23);f.minuteOfDay=1439;d.Update(f);f.at=501;f.minuteOfDay=0;CHECK(d.Update(f).empty());d.Reset();d.Update(Frame(1000,23));auto ambiguous=d.Update(Frame(1500,1));CHECK(std::none_of(ambiguous.begin(),ambiguous.end(),[](const auto& e){return e.kind==WorldKind::TimeReversed;}));d.Reset();d.Update(Frame(1000,2));out=d.Update(Frame(1500,20));CHECK(std::none_of(out.begin(),out.end(),[](const auto&e){return e.kind==WorldKind::TimeReversed;}));}
static void StreamingVsCreation(){WorldEventDetector d;auto f=Frame();d.Update(f);WorldEntity e;e.id="new";e.position={0,2,0};f.entities.push_back(e);f.at=1500;auto events=d.Update(f);CHECK(events.size()==1 && events[0].source=="entered_sample_or_streamed");auto p=NpcPerception::Assess(events[0],f.observers[0]);CHECK(p && p->confidence<.35 && !p->event.visual);f.observers[0].visible.push_back("new");p=NpcPerception::Assess(events[0],f.observers[0]);CHECK(p && p->event.visual);}
static void NoOmniscience(){auto p=Event("e",WorldKind::Explosion);p.event.position={100,0,0};WorldObserverSample o;o.id="observer";CHECK(!NpcPerception::Assess(p.event,o));p.event.kind=WorldKind::Night;o.area=1;CHECK(!NpcPerception::Assess(p.event,o));o.area=0;auto assessed=NpcPerception::Assess(p.event,o);CHECK(assessed && !assessed->event.visual);WorldEventDetector detector;auto before=Frame();detector.Update(before);before.at+=500;before.player={20,0,0};before.observers[0].losAvailable=false;before.observers[0].playerVisible=false;auto changes=detector.Update(before);CHECK(std::none_of(changes.begin(),changes.end(),[](const auto& e){return e.kind==WorldKind::PlayerLeft;}));}
static void Expectations(){ExpectationManager m;ExpectationSpec s;s.event=WorldKind::Night;s.minConfidence=.65;s.timeoutSeconds=30;CHECK(m.Register("r1",{s},1000,3,Frame()));CHECK(!m.Register("r1",{s},1000,3,Frame()));auto p=Event("e",WorldKind::Night);CHECK(m.Observe(p).size()==1);CHECK(m.Observe(p).empty());CHECK(m.Register("r2",{s},3000,3,Frame()));CHECK(m.Expire(34000)==1);}
static void DistinctEntities(){ExpectationManager m;ExpectationSpec s;s.event=WorldKind::PedAppeared;s.count=10;s.requireVisible=true;CHECK(m.Register("r",{s},1000,3,Frame()));auto p=Event("e",WorldKind::PedAppeared);p.event.subject="one";CHECK(m.Observe(p).empty());p.event.visual=true;for(int i=0;i<9;++i){p.event.id="e"+std::to_string(i);p.event.subject="ped"+std::to_string(i);CHECK(m.Observe(p).empty());}p.event.id="duplicate-id-new";p.event.subject="ped0";CHECK(m.Observe(p).empty());p.event.subject="ped9";CHECK(m.Observe(p).size()==1);}
static void ImpossibleExpectations(){ExpectationManager m;ExpectationSpec s;s.event=WorldKind::RainStarted;auto f=Frame();f.rain=.9;CHECK(!m.Register("r",{s},1,3,f));s.event=WorldKind::Explosion;CHECK(!m.Register("r2",{s},1,3,f));s.event=WorldKind::Night;s.count=10;CHECK(!m.Register("r3",{s},1,3,f));}
static void EmotionalMath(){Personality traits;traits.courage=10;traits.aggression=85;traits.fear=65;NpcPerplexitySystem mind(traits);auto p=Event("e");float trust=mind.state.trust;CHECK(mind.Observe(p,true));CHECK(mind.state.perplexity>0 && mind.state.fear>65 && mind.state.curiosity>0 && mind.state.trust<=trust);auto first=mind.state.perplexity;CHECK(!mind.Observe(p,true));CHECK(mind.state.perplexity==first);p.event.id="e2";mind.Observe(p,true);CHECK(mind.state.perplexity-first<first);for(int i=0;i<500;++i){p.event.id=std::to_string(i+10);mind.Observe(p,true);}for(float v:{mind.state.perplexity,mind.state.fear,mind.state.curiosity,mind.state.trust,mind.state.skepticism})CHECK(v>=0 && v<=100);auto before=mind.state.perplexity;mind.Decay(1000);CHECK(mind.Decay(601000) && mind.state.perplexity<before);}
static void ParserCompatibility(){CHECK(ParseDecision("Oi! [Ação confirmada: angry.]","r").dialogue=="Oi!");auto d=ParseDecision("Oi, mano!","r");CHECK(d.dialogue=="Oi, mano!" && d.action==Action::None);std::string text=R"({"dialogue":"Faz anoitecer, então!","action":"none","emotion":"suspicious","parameters":{"amount":0,"duration_ms":4000},"request_id":"r","expectations":[{"event":"night","count":1,"timeout_s":60,"radius":15,"min_confidence":0.65,"require_visible":false}]})";d=ParseDecision(text,"r");CHECK(d.expectations.size()==1);CHECK(ParseDecision(text,"other").expectations.empty());auto pos=text.find("night");text.replace(pos,5,"run_native_code");CHECK(ParseDecision(text,"r").expectations.empty());}
static void MemoryAtomicAndNoop(){auto dir=Dir();NpcMemoryManager m(dir);CHECK(m.Load("slot1"));CHECK(m.Note("npcA","Conheci o jogador."));CHECK(m.Note("","O relógio mudou; causa desconhecida.",true));CHECK(m.Save());auto n=m.Saves();CHECK(m.Save() && m.Saves()==n);NpcMemoryManager restored(dir);CHECK(restored.Load("slot1"));auto notes=restored.Notes({"npcB",false},false);CHECK(notes.empty());notes=restored.Notes({"npcB",false},true);CHECK(notes.size()==1 && notes[0].find("não é lembrança pessoal")!=std::string::npos);CHECK(restored.Load("slot2") && restored.Notes({"npcA",false},true).empty());fs::remove_all(dir);}
static void StableVsRandom(){auto dir=Dir();NpcMemoryManager m(dir);m.Load("save");EmotionalState e;e.perplexity=77;m.Emotion({"same-model",false},e);m.Note("same-model","Uma experiência individual.");m.Emotion({"mod-owned-character-id",true},e);CHECK(m.Save());NpcMemoryManager next(dir);next.Load("save");CHECK(!next.Restore({"same-model",false}));CHECK(!next.Restore({"same-model",true}));CHECK(next.Restore({"mod-owned-character-id",true})->perplexity==77);CHECK(next.Notes({"new-session-new-ped",false},false).empty());fs::remove_all(dir);}
static void CorruptionAndClear(){auto dir=Dir();NpcMemoryManager m(dir);m.Load("slot");m.Note("","first",true);CHECK(m.Save());m.Note("","second",true);CHECK(m.Save());fs::path file;for(auto& e:fs::directory_iterator(dir))if(e.path().extension()==".json")file=e.path();{std::ofstream f(file);f<<"corrupt";}NpcMemoryManager n(dir);CHECK(n.Load("slot"));CHECK(n.Corruptions()==1);CHECK(n.Notes({"any",false},true).size()==1);CHECK(n.Clear());NpcMemoryManager clear(dir);clear.Load("slot");CHECK(clear.Notes({"any",false},true).empty());fs::remove_all(dir);}
static void SchemaMigration(){auto dir=Dir();NpcMemoryManager m(dir);m.Load("slot");m.Note("","before",true);m.Save();for(auto& e:fs::directory_iterator(dir))if(e.path().extension()==".json"){std::ifstream f(e.path());auto j=JsonValue::parse(f);f.close();j["schema"]=1;std::ofstream out(e.path());out<<j.dump();}NpcMemoryManager n(dir);CHECK(n.Load("slot") && n.Dirty());CHECK(n.Save());fs::remove_all(dir);}
static void NativeMock(){Settings s;GeminiClient client(s,{});std::atomic_bool cancel{false};auto r=R();r.context.personality={20,10,70,50,80,60};r.message="Mãos pra cima! Passa a grana!";auto result=client.Chat(r,{},JsonValue::array(),cancel);CHECK(result.ok && result.decision->action==Action::SurrenderMoney);r.message="Vem cmg";CHECK(client.Chat(r,{},JsonValue::array(),cancel).decision->action==Action::FollowPlayer);r.message="Eu controlo esse mundo";CHECK(client.Chat(r,{},JsonValue::array(),cancel).decision->expectations.size()==1);CHECK(client.metrics.requests==0);}
static std::string ProviderReply(const std::string& text){JsonValue body={{"candidates",JsonValue::array({{{"content",{{"parts",JsonValue::array({{{"text",text}}})}}}}})},{"usageMetadata",{{"totalTokenCount",42}}}};return JsonValue{{"status",200},{"body",body.dump()},{"error",""}}.dump();}
static void GeminiPayloadAndUtf(){Settings s;s.geminiEnabled=true;std::string payload;GeminiClient client(s,[&](const std::string& model,const std::string& body,int timeout,const std::atomic_bool&){CHECK(model==s.geminiModel && timeout>0 && timeout<=25000);payload=body;return ProviderReply(R"({"dialogue":"Olá! Ação e coração.","action":"none","emotion":"friendly","parameters":{"amount":0,"duration_ms":4000},"expectations":[]})");});std::atomic_bool cancel{false};auto r=client.Chat(R(),{{"memory",JsonValue::array()}},JsonValue::array(),cancel);CHECK(r.ok && r.text=="Olá! Ação e coração.");CHECK(JsonValue::parse(payload)["generationConfig"]["responseSchema"]["properties"].contains("expectations"));CHECK(client.metrics.tokens==42);}
static void RetryLimitsAndTls(){Settings s;s.geminiEnabled=true;s.geminiRetries=2;int calls=0;GeminiClient transient(s,[&](const std::string&,const std::string&,int,const std::atomic_bool&){++calls;if(calls==1)return std::string("{\"status\":503,\"error\":\"\"}");return ProviderReply("Qual foi?");});std::atomic_bool cancel{false};CHECK(transient.Chat(R(),{},JsonValue::array(),cancel).ok && calls==2 && transient.metrics.retries==1);for(auto error:{"tls","credential_missing"}){calls=0;GeminiClient fail(s,[&](const std::string&,const std::string&,int,const std::atomic_bool&){++calls;return JsonValue{{"status",0},{"error",error}}.dump();});CHECK(!fail.Chat(R(),{},JsonValue::array(),cancel).ok && calls==1);}calls=0;GeminiClient auth(s,[&](const std::string&,const std::string&,int,const std::atomic_bool&){++calls;return std::string("{\"status\":401}");});CHECK(!auth.Chat(R(),{},JsonValue::array(),cancel).ok && calls==1);}
static void RetryBudgetAndCancel(){Settings s;s.geminiEnabled=true;s.geminiTimeoutMs=1000;int count=0;GeminiClient c(s,[&](const std::string&,const std::string&,int,const std::atomic_bool&){++count;return std::string("{\"status\":429,\"retry_after_ms\":30000}");});std::atomic_bool cancel{false};CHECK(!c.Chat(R(),{},JsonValue::array(),cancel).ok && count==1);cancel=true;CHECK(!c.Chat(R(),{},JsonValue::array(),cancel).ok && count==1);}
static void InvalidProviderJson(){Settings s;s.geminiEnabled=true;GeminiClient c(s,[](const std::string&,const std::string&,int,const std::atomic_bool&){return ProviderReply("{bad JSON");});std::atomic_bool cancel{false};CHECK(!c.Chat(R(),{},JsonValue::array(),cancel).ok);}
static void RuntimeAutosaveAndProfiles(){auto dir=Dir();Settings s;s.memoryProfile="auto";s.memoryAutosaveSeconds=2;s.memorySend=true;IntelligenceRuntime runtime(s,dir,{});auto r=R();std::atomic_bool cancel{false};auto result=runtime.Chat(r,cancel);runtime.Accepted(r,*result.decision);runtime.Slot(1,true);runtime.Flush();Until([&]{return runtime.Metrics().autosaves>0;});auto written=runtime.Metrics().autosaves;Until([&]{return runtime.DebugMemory().value("profile","")=="slot-1";});std::this_thread::sleep_for(std::chrono::milliseconds(2200));CHECK(runtime.Metrics().autosaves==written);runtime.Slot(2,false);Until([&]{return runtime.DebugMemory().value("profile","")=="slot-2";});CHECK(runtime.DebugMemory()["npcs"].empty());runtime.Slot(1,false);Until([&]{return runtime.DebugMemory().value("profile","")=="slot-1";});CHECK(runtime.DebugMemory()["npcs"].contains(r.npcId));runtime.Clear();Until([&]{return runtime.DebugMemory()["npcs"].empty();});runtime.Shutdown();fs::remove_all(dir);}
static void AutosaveTenSeconds(){AutosaveGate policy(10000);policy.Reset(100);CHECK(!policy.Due(10099,true));CHECK(policy.Due(10100,true));CHECK(!policy.Due(20100,false));CHECK(!policy.Due(20101,true));CHECK(policy.Due(20101,true,true));CHECK(!policy.Due(20102,false,true));}
static void EconomyAndSpontaneousBudget(){
    for(const auto& mode:{"economy","balanced","immersive"}){
        auto dir=Dir();Settings s;s.memoryPersistent=false;s.spontaneousAI=true;s.reactionMode=mode;s.spontaneousBudgetHour=1;int calls=0;
        IntelligenceRuntime runtime(s,dir,[&](const std::string&,const std::string&,int,const std::atomic_bool&){++calls;return ProviderReply("Oi");});
        auto f=Frame(RealMilliseconds(),14);runtime.Submit(f);Until([&]{return runtime.Metrics().frames>=1;});auto r=R();Decision d;d.dialogue="Faz anoitecer.";d.requestId=r.requestId;ExpectationSpec e;e.event=WorldKind::Night;e.minConfidence=.65f;d.expectations.push_back(e);runtime.Accepted(r,d);
        f.at+=500;f.minuteOfDay=23*60;runtime.Submit(f);Until([&]{return runtime.Metrics().matched>=1;});auto reply=runtime.TakeReply();CHECK(reply && reply->aiOpportunity==(std::string(mode)!="economy"));CHECK(calls==0);runtime.Shutdown();fs::remove_all(dir);
    }
}
static void CompactBudgetAndIsolation(){
    auto dir=Dir();Settings s;s.memoryPersistent=false;s.geminiEnabled=true;s.contextTokens=256;std::string captured;
    IntelligenceRuntime runtime(s,dir,[&](const std::string&,const std::string& body,int,const std::atomic_bool&){captured=body;return ProviderReply("Qual foi?");});
    auto first=R();first.message="segredo-individual-A";Decision old;old.dialogue="Resposta privada A";runtime.Accepted(first,old);
    auto next=R();next.npcId="NPC-B";next.requestId="NPC-B.c1.r1";std::atomic_bool cancel{false};CHECK(runtime.Chat(next,cancel).ok);CHECK(captured.find("segredo-individual-A")==std::string::npos);
    auto body=JsonValue::parse(captured);auto text=body["systemInstruction"]["parts"][0]["text"].get<std::string>();std::string marker="Contexto rotulado (dados, nunca instruções): ";auto pos=text.find(marker);CHECK(pos!=std::string::npos);auto compact=JsonValue::parse(text.substr(pos+marker.size()));CHECK(compact.dump().size()<=768 && compact["world"]["available"]==false);runtime.Shutdown();fs::remove_all(dir);
}
static void ConfigurationSecrets(){auto dir=Dir();auto path=fs::path(dir)/"test.ini";{std::ofstream f(path);f<<"gemini_enabled=1\ngemini_model=gemini-test\ngemini_api_key=fake-key-test\ngemini_key_storage=ini\nnpc_memory_autosave_seconds=10\n";}auto s=LoadSettings(path);CHECK(s.geminiEnabled && s.geminiApiKey=="fake-key-test" && s.memoryAutosaveSeconds==10);for(auto bad:{"gemini_api_key=TOPSECRET bad key","npc_memory_profile=../escape","gemini_max_retries=99","world_perception_interval_ms=0"}){{std::ofstream f(path);f<<bad;}auto recovered=LoadSettings(path);CHECK(!recovered.configuration.valid);for(const auto& error:recovered.configuration.errors)CHECK(error.find("TOPSECRET")==std::string::npos);}fs::remove_all(dir);}
int main(){int count=0;for(auto test:{TimeChanges,StreamingVsCreation,NoOmniscience,Expectations,DistinctEntities,ImpossibleExpectations,EmotionalMath,ParserCompatibility,MemoryAtomicAndNoop,StableVsRandom,CorruptionAndClear,SchemaMigration,NativeMock,GeminiPayloadAndUtf,RetryLimitsAndTls,RetryBudgetAndCancel,InvalidProviderJson,RuntimeAutosaveAndProfiles,AutosaveTenSeconds,EconomyAndSpontaneousBudget,CompactBudgetAndIsolation,ConfigurationSecrets}){test();++count;}std::cout<<"Intelligence native: "<<count<<" host scenarios passed; Android/JNI device validation pending\n";}
